// Mehlman HY Neuroanatomy
const neuroAnatomyQuestions = [
  // ===== NEUROANATOMY: Vascular Lesions + Homunculus =====
  { id: "na1", category: "Vascular Lesions", q: "27F with a long-standing history of seizures. MRI shown. Diagnosis?", a: "Arteriovenous malformation (AVM) - the MRI looks almost like swiss cheese. This is a HY image for Step 1.", img: "/qimg/neuro/fig-003-003.webp", alt: "Axial brain MRI showing an arteriovenous malformation with a swiss-cheese tangle of vessels" },
  { id: "na2", category: "Vascular Lesions", q: "82M with long-standing HTN has weakness of the right arm and right side of the face. Occlusion of which vessel?", a: "Left middle cerebral artery (MCA). MCA strokes cause deficits of the contralateral upper limb and face. The history of HTN suggests carotid atherosclerosis with a plaque launching off to the circle of Willis.", img: "/qimg/neuro/fig-004-006.webp", alt: "Photograph of the base of the brain showing the circle of Willis and its named vessels" },
  { id: "na3", category: "Vascular Lesions", q: "74F with atrial fibrillation has weakness of the left leg. Occlusion of which vessel?", a: "Right anterior cerebral artery (ACA). ACA strokes cause deficits of the contralateral lower limb. The history of AF suggests a left atrial mural thrombus launched off to the circle of Willis." },
  { id: "na4", category: "Vascular Lesions", q: "66M with HTN has weakness of the left arm. Is the stroke lesion on the left or right side of the brain?", a: "Right side - motor deficits are contralateral to the lesion." },
  { id: "na5", category: "Vascular Lesions", q: "66M with HTN has weakness of the left arm. Is the lesion medial or lateral in the cerebral hemisphere?", a: "Lateral - on the homunculus the upper limb and face are represented laterally, while the leg is medial.", img: "/qimg/neuro/fig-004-005.webp", alt: "Coronal homunculus diagram showing the motor and sensory strips with the leg medial and the upper limb and face lateral" },
  { id: "na6", category: "Vascular Lesions", q: "66M with HTN has weakness of the left arm. Is the lesion anterior or posterior to the central sulcus?", a: "Anterior - the primary motor cortex is anterior to the central sulcus; primary sensory is posterior.", img: "/qimg/neuro/fig-003-004.webp", alt: "Lateral diagram of the brain labeling the frontal, parietal, temporal, and occipital lobes and the central sulcus" },
  { id: "na7", category: "Vascular Lesions", q: "92F with atrial fibrillation has numbness and tingling of her right leg. Left or right side of the brain?", a: "Left - sensory deficits are contralateral to the lesion." },
  { id: "na8", category: "Vascular Lesions", q: "92F with AF has numbness and tingling of her right leg. Medial or lateral cerebral hemisphere?", a: "Medial - the homunculus represents the lower limb medially; upper limb and face are lateral.", img: "/qimg/neuro/fig-004-005.webp", alt: "Coronal homunculus diagram showing the motor and sensory strips with the leg medial and the upper limb and face lateral" },
  { id: "na9", category: "Vascular Lesions", q: "92F with AF has numbness and tingling of her right leg. Anterior or posterior to the central sulcus?", a: "Posterior - the primary sensory cortex is posterior to the central sulcus; primary motor is anterior." },
  { id: "na10", category: "Homunculus Map", q: "66M with chronic HTN managed with lisinopril has paresthesias of the left leg. Which letter on the coronal homunculus map is affected?", a: "F. The stroke affects the left side of the body, is sensory, and is lower limb - so the lesion must be contralateral (eliminating A-D on the left side of the brain), medial (lower limb per the homunculus), and posterior to the central sulcus (primary sensory cortex).", img: "/qimg/neuro/fig-005-coronal.webp", alt: "Coronal homunculus map with letters A through H marking motor and sensory regions for the limbs on each side" },
  { id: "na11", category: "Homunculus Map", q: "On the coronal homunculus map, a stroke at letter A causes what?", a: "Motor disturbance (paresis or paralysis) of the right arm and face.", img: "/qimg/neuro/fig-005-coronal.webp", alt: "Coronal homunculus map with letters A through H marking motor and sensory regions for the limbs on each side" },
  { id: "na12", category: "Homunculus Map", q: "On the coronal homunculus map, a stroke at letter B causes what?", a: "Sensory disturbance (numbness, paresthesias, pain) of the right arm and face.", img: "/qimg/neuro/fig-005-coronal.webp", alt: "Coronal homunculus map with letters A through H marking motor and sensory regions for the limbs on each side" },
  { id: "na13", category: "Homunculus Map", q: "On the coronal homunculus map, a stroke at letter C causes what?", a: "Motor disturbance of the right leg.", img: "/qimg/neuro/fig-005-coronal.webp", alt: "Coronal homunculus map with letters A through H marking motor and sensory regions for the limbs on each side" },
  { id: "na14", category: "Homunculus Map", q: "On the coronal homunculus map, a stroke at letter D causes what?", a: "Sensory disturbance of the right leg.", img: "/qimg/neuro/fig-005-coronal.webp", alt: "Coronal homunculus map with letters A through H marking motor and sensory regions for the limbs on each side" },
  { id: "na15", category: "Homunculus Map", q: "On the coronal homunculus map, a stroke at letter E causes what?", a: "Motor disturbance of the left leg.", img: "/qimg/neuro/fig-005-coronal.webp", alt: "Coronal homunculus map with letters A through H marking motor and sensory regions for the limbs on each side" },
  { id: "na16", category: "Homunculus Map", q: "On the coronal homunculus map, a stroke at letter F causes what?", a: "Sensory disturbance of the left leg.", img: "/qimg/neuro/fig-005-coronal.webp", alt: "Coronal homunculus map with letters A through H marking motor and sensory regions for the limbs on each side" },
  { id: "na17", category: "Homunculus Map", q: "On the coronal homunculus map, a stroke at letter G causes what?", a: "Motor disturbance of the left arm and face.", img: "/qimg/neuro/fig-005-coronal.webp", alt: "Coronal homunculus map with letters A through H marking motor and sensory regions for the limbs on each side" },
  { id: "na18", category: "Homunculus Map", q: "On the coronal homunculus map, a stroke at letter H causes what?", a: "Sensory disturbance of the left arm and face.", img: "/qimg/neuro/fig-005-coronal.webp", alt: "Coronal homunculus map with letters A through H marking motor and sensory regions for the limbs on each side" },
  // ===== NEUROANATOMY: Aphasia =====
  { id: "na19", category: "Aphasia", q: "91M with a history of AF has new-onset difficulty articulating speech - words come out telegraphic. Repetition is impaired, comprehension intact. Which letter on the lateral brain diagram is affected?", a: "A - the Broca area (inferior frontal gyrus, frontal lobe). Broca aphasia is non-fluent with repetition impaired; the patient comprehends without a problem and appears frustrated with the inability to articulate fluently.", img: "/qimg/neuro/fig-005-007.webp", alt: "Lateral brain diagram with letters marking the Broca area, auditory cortex, Wernicke area, angular gyrus, supramarginal gyrus, and arcuate fasciculus" },
  { id: "na20", category: "Aphasia", q: "On the lateral brain diagram, what does a lesion at letter B cause?", a: "Letter B is the primary auditory cortex. Not high yield, but labeled because NBME questions can show this lettered distribution and it is hard to distinguish B from C (Wernicke area).", img: "/qimg/neuro/fig-005-007.webp", alt: "Lateral brain diagram with letters marking the Broca area, auditory cortex, Wernicke area, angular gyrus, supramarginal gyrus, and arcuate fasciculus" },
  { id: "na21", category: "Aphasia", q: "On the lateral brain diagram, a lesion at letter C causes which aphasia and how does it present?", a: "C is the Wernicke area (superior temporal gyrus, temporal lobe). Wernicke aphasia is fluent with repetition impaired - word salad: the patient articulates without issue but makes no sense and also cannot comprehend.", img: "/qimg/neuro/fig-005-007.webp", alt: "Lateral brain diagram with letters marking the Broca area, auditory cortex, Wernicke area, angular gyrus, supramarginal gyrus, and arcuate fasciculus" },
  { id: "na22", category: "Aphasia", q: "On the lateral brain diagram, a lesion of the angular gyrus (letter D) causes what syndrome?", a: "Gerstmann syndrome - agraphia, right-left agnosia, finger agnosia, acalculia. The angular gyrus (parietal lobe) transfers information to the Wernicke area. Not overwhelmingly HY, but students carry an infatuation with it nevertheless.", img: "/qimg/neuro/fig-005-007.webp", alt: "Lateral brain diagram with letters marking the Broca area, auditory cortex, Wernicke area, angular gyrus, supramarginal gyrus, and arcuate fasciculus" },
  { id: "na23", category: "Aphasia", q: "On the lateral brain diagram, what is letter E and what happens if it is lesioned?", a: "E is the supramarginal gyrus. Not high yield, but labeled because an NBME question might show this lettered distribution. It is thought to play a role in empathy and interpreting people's gestures.", img: "/qimg/neuro/fig-005-007.webp", alt: "Lateral brain diagram with letters marking the Broca area, auditory cortex, Wernicke area, angular gyrus, supramarginal gyrus, and arcuate fasciculus" },
  { id: "na24", category: "Aphasia", q: "On the lateral brain diagram, a lesion at letter F (arcuate fasciculus) causes which aphasia?", a: "Conduction aphasia - impaired repetition only. The arcuate fasciculus connects Broca and Wernicke areas, so fluency and comprehension stay intact.", img: "/qimg/neuro/fig-005-007.webp", alt: "Lateral brain diagram with letters marking the Broca area, auditory cortex, Wernicke area, angular gyrus, supramarginal gyrus, and arcuate fasciculus" },
  { id: "na25", category: "Aphasia", q: "Stroke sounds like Broca aphasia but repetition is NOT impaired. Diagnosis?", a: "Transcortical motor aphasia." },
  { id: "na26", category: "Aphasia", q: "Stroke sounds like Wernicke aphasia but repetition is NOT impaired. Diagnosis?", a: "Transcortical sensory aphasia." },
  { id: "na27", category: "Aphasia", q: "Stroke sounds like Broca + Wernicke at the same time but repetition is NOT impaired. Diagnosis?", a: "Mixed transcortical aphasia." },
  { id: "na28", category: "Aphasia", q: "Stroke sounds like Broca + Wernicke at the same time AND repetition is impaired. Diagnosis?", a: "Global aphasia." },
  { id: "na29", category: "Aphasia", q: "72M with Broca aphasia - which vessel is affected?", a: "Left MCA. Always assume the left brain is dominant unless the question specifically says the patient is left-handed." },
  { id: "na30", category: "Aphasia", q: "72M with Wernicke aphasia - which vessel and which gyrus are affected?", a: "Left MCA, superior temporal gyrus of the temporal lobe. Broca is the inferior frontal gyrus of the frontal lobe - both are MCA territory, left side in most people." },
  // ===== NEUROANATOMY: Cortical Maps =====
  { id: "na31", category: "Cortical Maps", q: "On the lateral map of the dominant hemisphere, which letter marks the Broca area?", a: "A. The Broca area sits on the inferior frontal gyrus; a lesion gives non-fluent aphasia with repetition impaired and intact comprehension.", img: "/qimg/neuro/fig-007-008.webp", alt: "Lateral diagram of the dominant hemisphere with letters A through G marking the Broca area, premotor cortex, primary motor and sensory cortices, primary auditory cortex, Wernicke area, and occipital pole" },
  { id: "na32", category: "Cortical Maps", q: "On the lateral map of the dominant hemisphere, which letter marks the primary auditory cortex?", a: "E. It sits in the superior temporal gyrus near the Wernicke area (F), and a question can make E and F hard to tell apart.", img: "/qimg/neuro/fig-007-008.webp", alt: "Lateral diagram of the dominant hemisphere with letters A through G marking the Broca area, premotor cortex, primary motor and sensory cortices, primary auditory cortex, Wernicke area, and occipital pole" },
  { id: "na33", category: "Cortical Maps", q: "On the lateral map of the dominant hemisphere, which letter marks the Wernicke area?", a: "F, in the superior temporal gyrus. A lesion gives fluent aphasia with repetition impaired - word salad with no comprehension.", img: "/qimg/neuro/fig-007-008.webp", alt: "Lateral diagram of the dominant hemisphere with letters A through G marking the Broca area, premotor cortex, primary motor and sensory cortices, primary auditory cortex, Wernicke area, and occipital pole" },
  { id: "na34", category: "Cortical Maps", q: "On the lateral map of the dominant hemisphere: a lesion causes weakness of the right arm and face. Which letter?", a: "C, the lateral primary motor cortex - the upper limb and face are represented laterally on the motor strip.", img: "/qimg/neuro/fig-007-008.webp", alt: "Lateral diagram of the dominant hemisphere with letters A through G marking the Broca area, premotor cortex, primary motor and sensory cortices, primary auditory cortex, Wernicke area, and occipital pole" },
  { id: "na35", category: "Cortical Maps", q: "On the lateral map of the dominant hemisphere: a lesion causes numbness of the right arm and face. Which letter?", a: "D, the lateral primary sensory cortex (post-central gyrus) - the sensory strip mirrors the motor strip, upper limb and face lateral.", img: "/qimg/neuro/fig-007-008.webp", alt: "Lateral diagram of the dominant hemisphere with letters A through G marking the Broca area, premotor cortex, primary motor and sensory cortices, primary auditory cortex, Wernicke area, and occipital pole" },
  { id: "na36", category: "Cortical Maps", q: "On the medial sagittal brain map, which letter marks the corpus callosum?", a: "E. F is the thalamus just below it - thalamus letters love to confuse on sagittal diagrams.", img: "/qimg/neuro/fig-007-009.webp", alt: "Medial sagittal brain diagram with letters A through K marking the frontal lobe, medial premotor and primary motor and sensory cortices, corpus callosum, thalamus, midbrain, pons, medulla, and cerebellum" },
  { id: "na37", category: "Cortical Maps", q: "On the medial sagittal brain map: a post-stroke patient has weakness of the LEFT leg. Which letter?", a: "C, the medial primary motor cortex (pre-central gyrus) - the leg sits on the medial surface of the hemisphere.", img: "/qimg/neuro/fig-007-009.webp", alt: "Medial sagittal brain diagram with letters A through K marking the frontal lobe, medial premotor and primary motor and sensory cortices, corpus callosum, thalamus, midbrain, pons, medulla, and cerebellum" },
  { id: "na38", category: "Cortical Maps", q: "On the medial sagittal brain map: a post-stroke patient has paresthesias of the left leg. Which letter?", a: "D, the medial primary sensory cortex (post-central gyrus).", img: "/qimg/neuro/fig-007-009.webp", alt: "Medial sagittal brain diagram with letters A through K marking the frontal lobe, medial premotor and primary motor and sensory cortices, corpus callosum, thalamus, midbrain, pons, medulla, and cerebellum" },
  { id: "na39", category: "Cortical Maps", q: "On the medial sagittal brain map: the vignette mentions the patient PLANNING to move his left leg. Which letter?", a: "B, the medial premotor cortex. Premotor plans the movement; primary motor executes it.", img: "/qimg/neuro/fig-007-009.webp", alt: "Medial sagittal brain diagram with letters A through K marking the frontal lobe, medial premotor and primary motor and sensory cortices, corpus callosum, thalamus, midbrain, pons, medulla, and cerebellum" },
  { id: "na40", category: "Cortical Maps", q: "On the medial sagittal brain map, what do letters G, H, and I mark, top to bottom?", a: "G = midbrain, H = pons, I = medulla - the brainstem in descending order.", img: "/qimg/neuro/fig-007-009.webp", alt: "Medial sagittal brain diagram with letters A through K marking the frontal lobe, medial premotor and primary motor and sensory cortices, corpus callosum, thalamus, midbrain, pons, medulla, and cerebellum" },
  { id: "na41", category: "Cortical Maps", q: "On the medial sagittal brain map: a patient has truncal ataxia. Which letter?", a: "J, the cerebellar vermis. Vermis lesion -> truncal ataxia; hemisphere (K, posterior lobe) lesion -> limb ataxia ipsilateral to the lesion.", img: "/qimg/neuro/fig-007-009.webp", alt: "Medial sagittal brain diagram with letters A through K marking the frontal lobe, medial premotor and primary motor and sensory cortices, corpus callosum, thalamus, midbrain, pons, medulla, and cerebellum" },
  { id: "na42", category: "Cortical Maps", q: "A patient has right limb ataxia from a cerebellar lesion. Is the lesion on the right or left side?", a: "Right - cerebellar lesions cause IPSILATERAL limb ataxia, unlike cortical lesions, which are contralateral. Letter K (posterior lobe of cerebellum) on the medial map.", img: "/qimg/neuro/fig-007-009.webp", alt: "Medial sagittal brain diagram with letters A through K marking the frontal lobe, medial premotor and primary motor and sensory cortices, corpus callosum, thalamus, midbrain, pons, medulla, and cerebellum" },
  { id: "na43", category: "Cortical Maps", q: "On the lateral map of the non-dominant hemisphere, which letter marks the central sulcus?", a: "N. L (just behind the sensory strip) is the somatosensory association area, which integrates information from the primary sensory cortex.", img: "/qimg/neuro/fig-008-010.webp", alt: "Lateral diagram of the non-dominant hemisphere with letters L through S marking the somatosensory association area, lateral primary sensory and motor cortices, central sulcus, premotor cortex, frontal lobe, and superior temporal gyrus" },
  { id: "na44", category: "Cortical Maps", q: "On the lateral map of the non-dominant hemisphere: a post-stroke patient has sensory disturbance of the left arm and face. Which letter?", a: "M, the lateral primary sensory cortex (post-central gyrus).", img: "/qimg/neuro/fig-008-010.webp", alt: "Lateral diagram of the non-dominant hemisphere with letters L through S marking the somatosensory association area, lateral primary sensory and motor cortices, central sulcus, premotor cortex, frontal lobe, and superior temporal gyrus" },
  { id: "na45", category: "Cortical Maps", q: "On the lateral map of the non-dominant hemisphere: a post-stroke patient has weakness of the left arm and face. Which letter?", a: "O, the lateral primary motor cortex (pre-central gyrus).", img: "/qimg/neuro/fig-008-010.webp", alt: "Lateral diagram of the non-dominant hemisphere with letters L through S marking the somatosensory association area, lateral primary sensory and motor cortices, central sulcus, premotor cortex, frontal lobe, and superior temporal gyrus" },
  { id: "na46", category: "Cortical Maps", q: "On the lateral map of the non-dominant hemisphere: a post-stroke patient has apathy, disinhibition, and personality change. Which letter?", a: "Q, the frontal lobe. Frontal lesions give personality and behavior change, not weakness.", img: "/qimg/neuro/fig-008-010.webp", alt: "Lateral diagram of the non-dominant hemisphere with letters L through S marking the somatosensory association area, lateral primary sensory and motor cortices, central sulcus, premotor cortex, frontal lobe, and superior temporal gyrus" },
  { id: "na47", category: "Cortical Maps", q: "On the lateral map of the non-dominant hemisphere, what does letter R mark, and why is it labeled non-dominant?", a: "R is the superior temporal gyrus of the NON-dominant hemisphere. In most people the left superior temporal gyrus is dominant and contains the primary auditory cortex and Wernicke area, so the matching gyrus on the right is the non-dominant one.", img: "/qimg/neuro/fig-008-010.webp", alt: "Lateral diagram of the non-dominant hemisphere with letters L through S marking the somatosensory association area, lateral primary sensory and motor cortices, central sulcus, premotor cortex, frontal lobe, and superior temporal gyrus" },
  { id: "na48", category: "Cortical Maps", q: "On the lateral map of the non-dominant hemisphere: the vignette mentions the patient planning to move the left arm and face. Which letter?", a: "S, the lateral premotor cortex. Planning = premotor; executing = primary motor (O).", img: "/qimg/neuro/fig-008-010.webp", alt: "Lateral diagram of the non-dominant hemisphere with letters L through S marking the somatosensory association area, lateral primary sensory and motor cortices, central sulcus, premotor cortex, frontal lobe, and superior temporal gyrus" },
  // ===== NEUROANATOMY: Gross Specimen + Brainstem Cross-Sections =====
  { id: "na49", category: "Gross Specimen", q: "The USMLE shows you a gross brain specimen from below without the cerebellum and it is hard to tell which side is the frontal lobe. What landmark orients you?", a: "The olfactory bulbs and tracts - they sit on the frontal lobe. Recognize them and you can say ok, that is the frontal lobe.", img: "/qimg/neuro/fig-009-011.webp", alt: "Ventral view of a gross brain specimen with the olfactory bulbs and tracts visible and letters marking the lobes" },
  { id: "na50", category: "Gross Specimen", q: "72M with progressive personality change, apathy, and disinhibition - he pulls his pants down when guests come over. Where on the ventral specimen is the pathology, and what is the diagnosis?", a: "L, the frontal lobe. Diagnosis is frontotemporal dementia, classically apathy, disinhibition, and personality change.", img: "/qimg/neuro/fig-009-011.webp", alt: "Ventral view of a gross brain specimen with the olfactory bulbs and tracts visible and letters marking the lobes" },
  { id: "na51", category: "Brainstem Cross-Sections", q: "69F with a history of HTN has a stroke, and her tongue deviates to the left. Which letter on the medulla cross-section is the lesion, and what is the syndrome?", a: "A - medial medullary syndrome on the ipsilateral side. The rule: tongue deviation in a vignette means medial medulla of the SAME side, so pick the letter that is most medial on that side of the cross-section. Supplied by the paramedian branch of the anterior spinal artery (ASA).", img: "/qimg/neuro/fig-012-015.webp", alt: "Cross-section of the medulla with letters marking medial and lateral territories" },
  { id: "na52", category: "Brainstem Cross-Sections", q: "A stroke vignette includes hoarseness, dysphagia, and Horner syndrome. Which letter and which artery on the medulla cross-section?", a: "B - lateral medullary (Wallenberg) syndrome, ipsilateral side. The artery is PICA; if PICA is not listed, choose the vertebral artery. Remember PICACHEW: PICA + CHEW (dysphagia). Horner syndrome here is a huge giveaway - do not let it pull you toward Pancoast tumor.", img: "/qimg/neuro/fig-012-015.webp", alt: "Cross-section of the medulla with letters marking medial and lateral territories" },
  // ===== NEUROANATOMY: Pons + Midbrain =====
  { id: "na53", category: "Brainstem Cross-Sections", q: "70M with HTN has a stroke: left-sided Bell palsy, left-sided hearing loss, and loss of temperature and pain on the left face and right body. Which letter on the pons slice and which artery?", a: "B - lateral pontine syndrome. The Bell palsy is literally the key detail. Caused by an AICA lesion - mnemonic FACIAL (Face is affected, and FACIAL contains AICA backwards). Rule: stroke + Bell palsy -> choose the lateral letter on the ipsilateral side of the pons slice.", img: "/qimg/neuro/fig-013-017.webp", alt: "Cross-section of the pons with letters marking medial and lateral territories" },
  { id: "na54", category: "Brainstem Cross-Sections", q: "What can medial pontine syndrome cause, and why does it matter on cross-sections?", a: "Abducens (CN VI) nerve palsy - the patient can have esotropia (medially directed eye). Lower yield than the lateral syndromes, but be aware of it.", img: "/qimg/neuro/fig-013-017.webp", alt: "Cross-section of the pons with letters marking medial and lateral territories" },
  { id: "na55", category: "Pons", q: "A pons CT shows a central lesion. The patient was recently treated for hyponatremia. Diagnosis, cause, and presentation?", a: "Central pontine myelinolysis from correcting hyponatremia TOO RAPIDLY with hypertonic saline. Presents as locked-in syndrome - inability to move the entire body except eye muscles: quadriplegia + aphonia + impaired horizontal eye movements. Do not confuse this with cerebral edema, which comes from correcting HYPERnatremia too quickly with hypotonic saline.", img: "/qimg/neuro/fig-014-018.webp", alt: "CT scan of the pons showing a central low-density lesion of central pontine myelinolysis" },
  { id: "na56", category: "Midbrain", q: "On the midbrain cross-section: identify the crus cerebri, CN III nucleus, cerebral aqueduct, and substantia nigra (letters A-D).", a: "A = crus cerebri, B = CN III (oculomotor) nucleus, C = cerebral aqueduct, D = substantia nigra. HY point: crus cerebri lesions cause contralateral spastic paralysis.", img: "/qimg/neuro/fig-015-020.webp", alt: "Cross-section of the midbrain with letters marking the crus cerebri, oculomotor nucleus, cerebral aqueduct, and substantia nigra" },
  { id: "na57", category: "Midbrain", q: "78M with HTN: left eye directed laterally and inferiorly plus weakness of the right side of the body. Diagnosis?", a: "Weber syndrome - a midbrain lesion causing ipsilateral oculomotor nerve (CN III) palsy plus contralateral hemiparesis (loss of crus cerebri). Lesion is in the paramedian branch of the posterior cerebral artery (PCA). Rule: stroke syndrome with oculomotor palsy -> choose Weber syndrome." },
  { id: "na58", category: "Midbrain", q: "75F had a cerebral infarction many years ago. Her brain on autopsy is shown, with the right crus cerebri infarcted. What would her main deficit have been?", a: "Spastic paralysis on the LEFT side of the body. The crus cerebri carries the pyramidal tract, so a crus cerebri lesion causes contralateral spastic paralysis.", img: "/qimg/neuro/fig-016-022.webp", alt: "Autopsy brain specimen showing an old infarction of the right crus cerebri" },
  { id: "na59", category: "Midbrain", q: "On the posterior midbrain diagram, what are the inferior colliculi (letters A and F) part of?", a: "The auditory system - they play a role in sound processing.", img: "/qimg/neuro/fig-017-024.webp", alt: "Posterior view of the midbrain with letters marking the inferior colliculi, pyramidal tracts, and medial longitudinal fasciculi" },
  { id: "na60", category: "Midbrain", q: "32F with one week of urinary urge incontinence cannot adduct her left eye when gazing right; convergence is preserved. Which letter on the midbrain diagram is the pathology, and what is the diagnosis?", a: "D - the left medial longitudinal fasciculus. This is MLF syndrome (internuclear ophthalmoplegia) in multiple sclerosis; the urge incontinence is the MS clue. Normal convergence means CN III is intact bilaterally. Rule: the side that cannot adduct is the side of the pathology, so all right-sided letters are eliminated - then just choose the letter that is most medial, because the condition is named the medial longitudinal fasciculus.", img: "/qimg/neuro/fig-017-024.webp", alt: "Posterior view of the midbrain with letters marking the inferior colliculi, pyramidal tracts, and medial longitudinal fasciculi" },
  { id: "na61", category: "Midbrain", q: "Mechanism of internuclear ophthalmoplegia: why does the left eye fail to adduct on right gaze, and what does the right eye do?", a: "Looking right activates right CN VI and left CN III in unison, and that unison requires the LEFT MLF. With a left MLF lesion the right eye abducts fine, the left eye fails to adduct, and the right eye shows nystagmus back toward the midline. MLF syndrome is pathognomonic for MS." },
  { id: "na62", category: "Midbrain", q: "MS patients can also get optic neuritis - change in visual acuity, color vision, central scotoma. Is it pathognomonic for MS?", a: "No - optic neuritis can be seen in other circumstances, such as ethambutol or sildenafil use. MLF syndrome is the one that is pathognomonic for MS (exceedingly rare exception: stroke from HTN)." },
  { id: "na63", category: "Midbrain", q: "74M with a unilateral resting tremor and shuffling gait. Which letter on the sagittal MRI is the pathology?", a: "D, the midbrain - the substantia nigra pars compacta (highlighted in blue) sits bilaterally in the midbrain. Parkinson disease.", img: "/qimg/neuro/fig-019-027.webp", alt: "Sagittal brain MRI with the substantia nigra pars compacta highlighted in blue and letters marking structures including the optic nerve, medial orbital gyrus, parietal lobe, midbrain, cerebellar vermis, and occipital pole" },
  { id: "na64", category: "Midbrain", q: "On the Parkinson sagittal MRI, identify letters A, B, C, E, and F (D is the midbrain).", a: "A = optic nerve, B = medial orbital gyrus, C = parietal lobe, E = cerebellar vermis, F = occipital pole of the occipital lobe.", img: "/qimg/neuro/fig-019-027.webp", alt: "Sagittal brain MRI with the substantia nigra pars compacta highlighted in blue and letters marking structures including the optic nerve, medial orbital gyrus, parietal lobe, midbrain, cerebellar vermis, and occipital pole" },
  // ===== NEUROANATOMY: Cranial Nerves =====
  { id: "na65", category: "Cranial Nerves", q: "32F hiking in Connecticut develops a circular rash on her forearm and a Bell palsy. Which nerve on the brainstem diagram explains her findings?", a: "H - the facial nerve (CN VII). Bell palsy secondary to Lyme disease.", img: "/qimg/neuro/fig-020-029.webp", alt: "Ventral brainstem diagram with letters marking the cranial nerves from the trigeminal through the vagus" },
  { id: "na66", category: "Cranial Nerves", q: "76M has a stroke, and his uvula deviates to the LEFT when he says ahh. Which letter on the brainstem diagram?", a: "E - the RIGHT vagus nerve; the uvula deviates to the contralateral side of the lesion. Other letters: A = right trochlear, B = right facial, C = right vestibulocochlear, D = right glossopharyngeal, F = left trigeminal, G = left facial, H = left vestibulocochlear, I = left glossopharyngeal, J = left vagus.", img: "/qimg/neuro/fig-020-029.webp", alt: "Ventral brainstem diagram with letters marking the cranial nerves from the trigeminal through the vagus" },
  { id: "na67", category: "Cranial Nerves", q: "Exit points: which foramina do V1, V2, and V3 pass through, and what is the mnemonic?", a: "V1 -> superior orbital fissure, V2 -> foramen rotundum, V3 -> foramen ovale. Mnemonic: Standing Room Only." },
  { id: "na68", category: "Cranial Nerves", q: "47M: touching the face just lateral to the nose produces pain. Through where does the nerve supplying this area exit the skull?", a: "Foramen rotundum - the maxillary branch (V2) of the trigeminal nerve supplies the cheek area lateral to the nose." },
  { id: "na69", category: "Cranial Nerves", q: "Light reflex: which cranial nerves are the afferent and efferent components? Corneal reflex?", a: "Light reflex: CN II afferent, CN III efferent (constricts the pupil via parasympathetics). Corneal reflex: V1 afferent, CN VII efferent." },
  { id: "na70", category: "Cranial Nerves", q: "19M with a viral infection and a right Bell palsy - what OTHER finding might result from the same nerve lesion?", a: "Right-sided hyperacusis (sounds too loud). CN VII innervates the stapedius muscle, which dampens sound via the stapes; a lesion loses that dampening." },
  { id: "na71", category: "Cranial Nerves", q: "Which nerves run the gag reflex, and which end is which?", a: "CN IX (glossopharyngeal) is the afferent limb, CN X (vagus) is the efferent limb." },
  { id: "na72", category: "Cranial Nerves", q: "35F with complete loss of hearing in the left ear - which cranial nerve is damaged?", a: "Left vestibulocochlear nerve (CN VIII)." },
  { id: "na73", category: "Cranial Nerves", q: "UMN versus LMN facial nerve lesion: how does each present?", a: "UMN lesion -> contralateral mid and lower facial paralysis with the forehead SPARED. LMN lesion -> ipsilateral Bell palsy affecting the whole half of the face. CN VII is also the efferent limb of the corneal reflex." },
  // ===== NEUROANATOMY: Circle of Willis + Vascular Syndromes =====
  { id: "na74", category: "Circle of Willis", q: "48F with a history of cystic kidneys has an enlarged right pupil. An aneurysm of which vessel (which letter on the ventral brain angiogram)?", a: "B - the posterior communicating artery. PCoM aneurysms cause ipsilateral mydriasis (blown pupil). ADPKD carries a risk of ACoM and PCoM aneurysms. A = right internal carotid artery, C = posterior cerebral artery, D = frontal lobe, E = olfactory tract, F = basilar artery, G = posterior inferior cerebellar artery.", img: "/qimg/neuro/fig-022-032.webp", alt: "Ventral brain angiogram illustration with letters marking the internal carotid, posterior communicating, posterior cerebral, basilar, and cerebellar arteries" },
  { id: "na75", category: "Circle of Willis", q: "82F with AF cannot move any muscle of her body except her eyes. Which letter on the circle of Willis angiogram is the stroke, and what is the syndrome?", a: "F - basilar artery stroke causing locked-in syndrome. A = ACA, B = ACoM, C = MCA, D = internal carotid artery, E = PCA, G = vertebral artery.", img: "/qimg/neuro/fig-023-033.webp", alt: "Angiogram of the circle of Willis with letters marking the ACA, ACoM, MCA, internal carotid, PCA, basilar, and vertebral arteries" },
  { id: "na76", category: "Circle of Willis", q: "68M with HTN has acute-onset PAINLESS loss of vision in the right eye. Which letter on the carotid illustration marks the embolus path, and what is the diagnosis?", a: "D - the ophthalmic artery. This is central retinal artery occlusion from a carotid plaque launched off secondary to HTN; the central retinal artery is a branch of the ophthalmic artery. A = ACoM, B = ACA, C = MCA, E = PCoM, F = internal carotid artery, G = choroidal artery, H = PCA.", img: "/qimg/neuro/fig-023-034.webp", alt: "Illustration of the internal carotid artery and its branches including the ophthalmic artery, with letters A through H" },
  { id: "na77", category: "Circle of Willis", q: "32M with fainting episodes has lower blood pressure in the right arm than the left. Retrograde flow through which vessel (which letter on the aortic arch diagram)?", a: "D - the right vertebral artery. This is subclavian steal syndrome: proximal stenosis of the subclavian artery causes retrograde flow through the vertebral artery, its first branch. A = right internal carotid, B = right external carotid, C = right common carotid, E = right subclavian, F = brachiocephalic, G = left internal carotid, H = left subclavian, I = left common carotid, J = aortic arch.", img: "/qimg/neuro/fig-024-035.webp", alt: "Angiogram illustration of the aortic arch branches with letters marking the carotid, subclavian, and vertebral arteries" },
  // ===== NEUROANATOMY: Cerebellum + Brachial Plexus + Cord =====
  { id: "na78", category: "Cerebellum", q: "34F in a boating accident now has dysmetria of the right side of the body with normal strength. Which letter on the sagittal brain section?", a: "F - the cerebellar hemisphere (posterior lobe). Cerebellar injuries cause IPSILATERAL dysmetria. Choice E, the cerebellar vermis, would cause truncal ataxia instead. A = thalamus, B = midbrain, C = pons, D = medulla.", img: "/qimg/neuro/fig-025-036.webp", alt: "Sagittal brain cross-section with letters marking the thalamus, midbrain, pons, medulla, cerebellar vermis, and cerebellar hemisphere" },
  { id: "na79", category: "Brachial Plexus", q: "26M has his arm slashed in a bar fight and presents with the arm pronated and unable to extend the wrist. Which letter on the brachial plexus diagram?", a: "C - the radial nerve (wrist drop, waiter's tip posture region). A = musculocutaneous, B = axillary, D = median, E = ulnar. The USMLE gives a straightforward deficit but makes you map it onto the plexus.", img: "/qimg/neuro/fig-026-038.webp", alt: "Brachial plexus diagram with letters marking the musculocutaneous, axillary, radial, median, and ulnar nerves" },
  { id: "na80", category: "Spinal Cord Tracts", q: "What does the spinothalamic tract carry?", a: "Pain and temperature. HIGH YIELD." },
  { id: "na81", category: "Spinal Cord Tracts", q: "What do the dorsal columns carry, and how are they organized?", a: "Vibration and proprioception. Fasciculus cuneatus carries the upper limbs and trunk; fasciculus gracilis carries the lower limbs. HIGH YIELD." },
  { id: "na82", category: "Spinal Cord Tracts", q: "What do the anterior and lateral corticospinal tracts carry?", a: "Motor function. HIGH YIELD." },
  { id: "na83", category: "Spinal Cord Tracts", q: "Identify the spinal cord cross-section structures: dorsal horn, dorsal root, dorsal root ganglion, lateral horn, ventral horn, anterior white commissure, ventral root, spinal nerve (letters A-H).", a: "A = dorsal horn, B = dorsal root, C = dorsal root ganglion, D = lateral horn, E = ventral horn, F = anterior white commissure, G = ventral root, H = spinal nerve.", img: "/qimg/neuro/fig-027-039.webp", alt: "Spinal cord cross-section with letters marking the dorsal horn, dorsal root and its ganglion, lateral horn, ventral horn, anterior white commissure, ventral root, and spinal nerve" },
  { id: "na84", category: "Spinal Cord Tracts", q: "On the cord tract map, identify: right corticospinal, right spinothalamic, right cuneatus, right gracilis, and the left-sided equivalents (letters A-H).", a: "A = right corticospinal tract, B = right spinothalamic tract, C = right fasciculus cuneatus, D = right fasciculus gracilis, E = left fasciculus gracilis, F = left fasciculus cuneatus, G = left corticospinal tract, H = left spinothalamic tract.", img: "/qimg/neuro/fig-027-040.webp", alt: "Spinal cord cross-section tract map with letters marking the corticospinal tracts, spinothalamic tracts, fasciculus cuneatus, and fasciculus gracilis on both sides" },
  { id: "na85", category: "Spinal Cord Tracts", q: "45M died years after a boating accident; autopsy with a myelin stain is shown. What deficit did he most likely have?", a: "Loss of vibration and proprioception of the lower limbs - there are bilateral lesions of the fasciculus gracilis of the dorsal columns. It is the only white-matter part of the cord NOT stained black, meaning it was demyelinated.", img: "/qimg/neuro/fig-028-042.webp", alt: "Myelin-stained spinal cord cross-section at autopsy showing a degenerated tract" },
  // ===== NEUROANATOMY: Cord Syndromes =====
  { id: "na86", category: "Cord Syndromes", q: "43F cannot sense pain and temperature over the right lower extremity. Which letter on the cord cross-section?", a: "J - the LEFT spinothalamic tract; spinothalamic lesions are CONTRALATERAL (the tract crosses in the anterior white commissure). A = right spinothalamic, B = right lateral corticospinal, C = right cuneatus, D = right anterior corticospinal, E = right gracilis, F = left gracilis, G = left anterior corticospinal, H = left cuneatus, I = left lateral corticospinal.", img: "/qimg/neuro/fig-029-044.webp", alt: "Spinal cord cross-section with ten letters marking the spinothalamic, corticospinal, and dorsal column tracts on both sides" },
  { id: "na87", category: "Cord Syndromes", q: "24M with a viral infection: loss of left leg motor function, loss of left leg vibration and proprioception, and loss of right leg pain and temperature. Diagnosis?", a: "Brown-Sequard syndrome - hemisection of the spinal cord. Ipsilateral motor + vibration/proprioception loss, contralateral pain/temperature loss. Classically a stab wound, but can be autoimmune (lupus myelitis) or viral." },
  { id: "na88", category: "Cord Syndromes", q: "67M with a long history of cervical spondylosis is rear-ended in an MVA, gets whiplash, and now has weakness in the upper limbs GREATER than the lower limbs. Diagnosis?", a: "Central cord syndrome. It is the answer when upper-limb weakness exceeds lower-limb weakness, typically after a hyperextension neck injury (whiplash in a rear-end MVA).", img: "/qimg/neuro/fig-030-046.webp", alt: "Spinal cord cross-section diagram showing the central cord region affected in central cord syndrome" },
  { id: "na89", category: "Cord Syndromes", q: "69M with long-standing T2DM: bilateral loss of motor function and pain/temperature below the nipples, with vibration and proprioception intact. Diagnosis?", a: "Anterior cord syndrome - the dorsal columns are spared. Often due to atherosclerosis with infarction of the anterior spinal artery. It is the answer when vibration/proprioception is preserved but motor + pain/temperature are lost, classically in a patient with arterial disease.", img: "/qimg/neuro/fig-030-047.webp", alt: "Spinal cord cross-section diagram showing the anterior cord territory affected in anterior cord syndrome" },
  { id: "na90", category: "Cord Syndromes", q: "23M with neurologic dysfunction; a myelin-stained cord cross-section shows the dorsal columns as the only unstained region, with motor and pain/temperature intact. Diagnosis?", a: "Tabes dorsalis (neurosyphilis) - isolated loss of the dorsal columns, so isolated loss of vibration and proprioception. The unstained region reflects demyelination.", img: "/qimg/neuro/fig-031-048.webp", alt: "Myelin-stained spinal cord cross-section showing the dorsal columns unstained by demyelination" },
  { id: "na91", category: "Cord Syndromes", q: "31M after a motorcycle accident has a lesion of the anterior white commissure on a cord cross-section. What dysfunction is most likely, and what is the condition?", a: "Bilateral loss of pain and temperature - syringomyelia. The crossing spinothalamic fibers in the anterior white commissure are hit. Can be due to trauma, infections, and classically Chiari I.", img: "/qimg/neuro/fig-031-049.webp", alt: "Spinal cord cross-section showing a central lesion at the anterior white commissure" },
  { id: "na92", category: "Cord Syndromes", q: "54M with clonus and a Babinski reflex in the left foot, fasciculations in the right hand, brisk reflexes, and elevated CK. Diagnosis?", a: "Amyotrophic lateral sclerosis (ALS, Lou Gehrig disease) - the mix of upper motor neuron signs (clonus, Babinski, brisk reflexes) and lower motor neuron signs (fasciculations) is the giveaway." },
  { id: "na93", category: "Cord Syndromes", q: "What are the two diagnostic components of ALS, and what finding RULES IT OUT?", a: "1) A combination of UMN findings (Babinski, clonus, brisk reflexes, increased tone) and LMN findings (fasciculations, decreased reflexes and tone, muscle atrophy) - the lateral corticospinal tracts and anterior horns degenerate, and CK can be elevated from increased tone. 2) There must be NO sensory findings - any paresthesias or numbness in the vignette and ALS is the wrong answer. The USMLE will often give the vignette and the answer is simply motor neurons. (For 2CK: the diagnostic test is EMG and nerve conduction studies.)" },
  { id: "na94", category: "Cord Syndromes", q: "55M immigrant from Albania sees a GP for the first time; his left leg has remarkably decreased muscle bulk and diminished motor function. Diagnosis and lesion location?", a: "Polio - loss of the anterior horns of the spinal cord. Anterior horns are also the answer for progressive infantile spinal muscular atrophy (Werdnig-Hoffman syndrome): profound hypotonia, absent reflexes, tongue fasciculations." },
  // ===== NEUROANATOMY: Basal Ganglia + Internal Capsule =====
  { id: "na95", category: "Basal Ganglia", q: "23F with a unilateral resting tremor, elevated ALT/AST, and low hematocrit. Which letter on the MRI labels the putamen?", a: "B - the putamen. A = caudate nucleus, C = globus pallidus. Parkinsonism in a young patient is Wilson disease until proven otherwise; copper deposition can occur anywhere in the basal ganglia, and the putamen is the classic location.", img: "/qimg/neuro/fig-033-052.webp", alt: "Axial brain MRI with letters marking the caudate nucleus, putamen, and globus pallidus" },
  { id: "na96", category: "Basal Ganglia", q: "41M with one year of jerking movements of the extremities, six months of worsening dementia, and a father who had the same and died at 56. Which letter on the MRI is the pathology?", a: "B - the caudate nucleus (Huntington disease; caudate atrophy). A = anterior horn of the lateral ventricle, C = internal capsule, D = putamen, E = third ventricle, F = thalamus.", img: "/qimg/neuro/fig-034-053.webp", alt: "Axial brain MRI showing caudate atrophy, with letters marking the caudate, ventricles, internal capsule, putamen, and thalamus" },
  { id: "na97", category: "Basal Ganglia", q: "Identify on the coronal basal ganglia section: medial frontal gyrus, middle frontal gyrus, caudate, internal capsule, thalamus, occipital pole (letters A-F).", a: "A = frontal lobe (medial frontal gyrus), B = frontal lobe (middle frontal gyrus), C = caudate nucleus, D = internal capsule, E = thalamus, F = occipital lobe (occipital pole).", img: "/qimg/neuro/fig-034-054.webp", alt: "Axial brain section with letters marking the frontal gyri, caudate nucleus, internal capsule, thalamus, and occipital pole" },
  { id: "na98", category: "Internal Capsule", q: "78M with long HTN has sudden paresis of the entire left side. Which letter on the specimen, which limb, and which vessels?", a: "C - the posterior limb of the internal capsule (A = anterior limb, B = genu). Supplied by the lenticulostriate vessels; chronic hypertension causes lipohyalinosis and compromise of these vessels. Posterior limb infarcts cause pure motor strokes with contralateral hemiparesis.", img: "/qimg/neuro/fig-035-055.webp", alt: "Brain specimen cross-section with letters marking the anterior limb, genu, and posterior limb of the internal capsule" },
  { id: "na99", category: "Internal Capsule", q: "63M with longstanding HTN has acute-onset flailing movements of the left arm. Which letter on the corpus striatum cross-section?", a: "E - the subthalamic nucleus (hemiballismus). A = hippocampus, B = crus cerebri, C = ventral medial nucleus of thalamus, D = substantia nigra, F = ventral lateral nucleus of thalamus.", img: "/qimg/neuro/fig-036-056.webp", alt: "Cross-section of the corpus striatum and diencephalon with letters marking the hippocampus, crus cerebri, thalamic nuclei, substantia nigra, and subthalamic nucleus" },
  // ===== NEUROANATOMY: Ventricles + Hemorrhage =====
  { id: "na100", category: "Sagittal Identify", q: "Identify on the midline sagittal specimen: corpus callosum, thalamus, pituitary gland, medulla, clivus, cerebellum, pineal gland, superior sagittal sinus, torcular herophili (letters A-I).", a: "A = corpus callosum, B = thalamus, C = pituitary gland, D = medulla, E = clivus, F = cerebellum, G = pineal gland, H = superior sagittal sinus, I = torcular herophili.", img: "/qimg/neuro/fig-036-057.webp", alt: "Midline sagittal brain specimen or diagram with letters A through I marking midline structures including the corpus callosum, pituitary, pineal gland, and venous sinuses" },
  { id: "na101", category: "Ventricles", q: "32M presents with hydrocephalus; MRI shows a colloid cyst. Where is it located (which letter on the ventricular illustration)?", a: "C - the foramen of Monro. Colloid cysts almost always originate from the roof of the anterior third ventricle, just posterior to the foramen of Monro. A = frontal horn, B = third ventricle, D = temporal horn, E = lateral ventricles, F = aqueduct of Sylvius, G = fourth ventricle, H = occipital horn.", img: "/qimg/neuro/fig-037-058.webp", alt: "Illustration of the ventricular system with letters marking the frontal, temporal, and occipital horns, third and fourth ventricles, foramen of Monro, and aqueduct" },
  { id: "na102", category: "Ventricles", q: "Connections: what does the foramen of Monro connect, and what does the cerebral aqueduct of Sylvius connect?", a: "Foramen of Monro connects the third ventricle to BOTH lateral ventricles. The aqueduct of Sylvius connects the third and fourth ventricles." },
  { id: "na103", category: "Ventricles", q: "72M with unsteady gait, personality change, urinary incontinence, and parkinsonism. The enlarged structures on CT are derived from which component of brain development?", a: "The telencephalon of the prosencephalon. Dilated lateral ventricles in normal pressure hydrocephalus - wet, wobbly, wacky, +/- parkinsonism.", img: "/qimg/neuro/fig-038-061.webp", alt: "Head CT showing dilated lateral ventricles of normal pressure hydrocephalus" },
  { id: "na104", category: "Hemorrhage", q: "84M with one year of progressive cognitive decline and NO history of HTN, CVD, or AF has a stroke and dies. Which of the four head CTs (letters A-D) fits?", a: "D - intracerebral (intraparenchymal) hemorrhage. The diagnosis is amyloid angiopathy causing hemorrhagic stroke in Alzheimer disease. A = subdural, B = epidural, C = subarachnoid.", img: "/qimg/neuro/fig-039-062.webp", alt: "Panel of four head CTs labeled A through D showing subdural, epidural, subarachnoid, and intraparenchymal hemorrhage" },
  { id: "na105", category: "Hemorrhage", q: "Subdural hematoma: vessel, shape, and classic settings?", a: "Rupture of the bridging (superior cerebral) veins; crescent-shaped, NO lucid interval; can accumulate slowly and look heterogeneous from mixed dried and fresh blood. Higher risk in the elderly, dementia patients, and alcoholics; the answer in acceleration-deceleration injuries (shaken baby syndrome, MVAs). NBME wants craniotomy as the treatment; with a decreased Glasgow score, intubate + hyperventilate first (lower CO2 lowers cerebral perfusion and intracranial pressure).", img: "/qimg/neuro/fig-039-062.webp", alt: "Panel of four head CTs labeled A through D showing subdural, epidural, subarachnoid, and intraparenchymal hemorrhage" },
  { id: "na106", category: "Hemorrhage", q: "Epidural hematoma: vessel, shape, and classic course?", a: "Rupture of the middle meningeal artery (branch of the external carotid); lens-shaped (biconvex), fast accumulating, WITH a lucid interval - the patient loses consciousness, returns to normal, goes home thinking he is okay, then dies. Low GCS: intubate + hyperventilate, then craniotomy. Normal GCS: just craniotomy.", img: "/qimg/neuro/fig-039-062.webp", alt: "Panel of four head CTs labeled A through D showing subdural, epidural, subarachnoid, and intraparenchymal hemorrhage" },
  { id: "na107", category: "Hemorrhage", q: "Subarachnoid hemorrhage: source, presentation, and risk factors?", a: "Rupture of an ACoM or PCoM saccular (berry) aneurysm - ACoM more common than PCoM. The patient often reports the worst headache of his life. PCoM aneurysms classically give an ipsilateral blown pupil from CN III impingement. HTN is the most common population risk factor; Ehlers-Danlos and ADPKD are the HY non-HTN specific causes.", img: "/qimg/neuro/fig-039-062.webp", alt: "Panel of four head CTs labeled A through D showing subdural, epidural, subarachnoid, and intraparenchymal hemorrhage" },
  { id: "na108", category: "Hemorrhage", q: "17M in a motorcycle accident has severe cognitive impairment two years later. MRI shows irregular areas of hyperintensity on diffusion-weighted imaging. Diagnosis and mechanism?", a: "Diffuse axonal injury, caused by shearing forces from the rapid-deceleration injury.", img: "/qimg/neuro/fig-041-064.webp", alt: "Diffusion-weighted brain MRI showing irregular hyperintensities of diffuse axonal injury" },
  // ===== NEUROANATOMY: Tumors + Malformations =====
  { id: "na109", category: "Brain Tumors", q: "44F with SLE has a ring-enhancing lesion on head CT. Diagnosis, and what is the trap answer?", a: "Primary CNS lymphoma - the wrong answer is toxoplasmosis. Ring-enhancing lesions can be abscess, malignancy, toxo, or neurocysticercosis. Autoimmune diseases (Hashimoto, SLE) and immunosuppression (AIDS) carry increased risk of primary CNS lymphoma.", img: "/qimg/neuro/fig-042-066.webp", alt: "Head CT showing a ring-enhancing lesion" },
  { id: "na110", category: "Brain Tumors", q: "3M with failure to thrive and a seizure. MRI shows a large solid and cystic lesion - solid component hyperintense, cystic component hypointense. Diagnosis?", a: "Pilocytic astrocytoma. This is a HY image for Step 1.", img: "/qimg/neuro/fig-042-067.webp", alt: "Brain MRI showing a large solid and cystic lesion of pilocytic astrocytoma" },
  { id: "na111", category: "Brain Tumors", q: "54M with three months of cognitive disturbance now has a seizure. Head CT shows a heterogeneous mass. Diagnosis, and why does it look heterogeneous?", a: "Glioblastoma multiforme (butterfly glioma). The heterogeneity comes from areas of necrosis and hemorrhage. It need not cross the midline, but when it does it is called a butterfly glioma.", img: "/qimg/neuro/fig-043-068.webp", alt: "Head CT showing a heterogeneous glioblastoma crossing the midline" },
  { id: "na112", category: "Brain Tumors", q: "16M developed cataracts at a young age and now has six months of left-sided tinnitus and hearing loss. His diagnosis matches the gross specimen shown. Underlying genetic condition?", a: "Neurofibromatosis type II (NF2). The diagnosis is acoustic schwannoma at the cerebellopontine junction - in a young patient think NF2, and it can become bilateral; in the elderly it is usually sporadic and unilateral.", img: "/qimg/neuro/fig-044-069.webp", alt: "Gross specimen showing an acoustic schwannoma at the cerebellopontine junction" },
  { id: "na113", category: "Brain Tumors", q: "56M with nine years of progressive right-sided hearing loss; MRI shows a large mass at the cerebellopontine junction. Which nerve and which cell type does it arise from?", a: "The vestibulocochlear nerve (CN VIII) and neural crest cells (Schwann cells derive from neural crest).", img: "/qimg/neuro/fig-044-070.webp", alt: "Cerebellopontine angle mass on MRI in a patient with progressive unilateral hearing loss" },
  { id: "na114", category: "Malformations", q: "MRI shows inferior herniation of the cerebellar tonsils. Diagnosis, and how do you split Chiari I from Chiari II?", a: "Chiari malformation. Chiari I = mere tonsillar herniation - the answer in a teenager or young adult, and it can be associated with syringomyelia. Chiari II (Arnold-Chiari) is more severe - the answer when a child has cerebellar herniation PLUS a lumbosacral myelomeningocele.", img: "/qimg/neuro/fig-045-071.webp", alt: "Sagittal MRI showing inferior herniation of the cerebellar tonsils in Chiari malformation" },
  { id: "na115", category: "Malformations", q: "Neural tube defects: when do they occur, how are they prevented, and what do they do to CSF markers?", a: "They occur between weeks 3-4 of gestation. The pregnant woman needs adequate folic acid (vitamin B9) before and during early pregnancy. Antiepileptics - particularly valproic acid, but also phenytoin and carbamazepine - are associated with them. They cause increased AFP and acetylcholinesterase in the CSF." },
  { id: "na116", category: "Malformations", q: "Newborn with a myelomeningocele - what developmental process was affected?", a: "Failure of closure of the caudal neuropore." },
  { id: "na117", category: "Malformations", q: "23F at 20 weeks gestation - ultrasound shows a fetus with anencephaly. Mechanism?", a: "Failure of closure of the rostral neuropore." },
  { id: "na118", category: "Malformations", q: "Neonate with a tuft of hair in the midline lumbar region and an absent spinous process on palpation. Mechanism?", a: "Failure of fusion of the sclerotomes (spina bifida occulta family)." },
  { id: "na119", category: "Malformations", q: "An MRI shows an absent cerebellar vermis with cystic dilation of the fourth ventricle. Diagnosis?", a: "Dandy-Walker malformation. That combination is all you need to know.", img: "/qimg/neuro/fig-047-073.webp", alt: "MRI showing Dandy-Walker malformation with absent cerebellar vermis and cystic fourth ventricle dilation" },
  { id: "na120", category: "Herniation", q: "Identify the six herniation types on the diagram (letters A-F).", a: "A = cingulate (subfalcine), B = transcalvarial, C = central transtentorial, D = uncal, E = upward transtentorial, F = tonsillar herniation.", img: "/qimg/neuro/fig-047-074.webp", alt: "Diagram of brain herniation types with letters A through F marking subfalcine, transcalvarial, transtentorial, uncal, upward, and tonsillar herniation" },
  { id: "na121", category: "Cranial Nerves", q: "The area labeled X on a neuron diagram is the node of Ranvier. Which channels are densely concentrated there?", a: "Sodium channels - high concentration at the nodes of Ranvier, which is what saltatory conduction runs on." },
  { id: "na122", category: "Cranial Nerves", q: "Identify the cranial nerve lesions: eye down and out; upward gaze with head tilted toward the unaffected side; medially directed eye.", a: "Down and out = CN III (oculomotor). Upward gaze + head tilt toward the unaffected side = CN IV (trochlear). Medially directed eye = CN VI (abducens).", img: "/qimg/neuro/fig-048-075.webp", alt: "Illustration of three eyes showing the gaze directions of CN III, CN IV, and CN VI lesions" },
  { id: "na123", category: "Cranial Nerves", q: "CN III palsy from a PCoM aneurysm versus from diabetes - which fibers does each hit and how do the presentations differ?", a: "PCoM aneurysmal compression hits the SUPERFICIAL parasympathetic efferents - ipsilateral mydriasis and loss of accommodation. Diabetes hits the DEEP extraocular muscle efferents - partial ptosis and the down-and-out eye." },
  { id: "na124", category: "Visual Pathway", q: "31F with multiple sclerosis has a visual problem - a contralateral inferior quadrantanopsia. Where is the lesion?", a: "Right parietal lobe. Parietal (superior) fibers of the optic radiations carry the inferior visual field - Meyer's loop in the temporal lobe carries the superior field.", img: "/qimg/neuro/fig-049-077.webp", alt: "Visual pathway diagram with lesions labeled and their corresponding visual field defects" },
  { id: "na125", category: "Visual Pathway", q: "45F with lung cancer has two weeks of progressive loss of the left visual field of BOTH eyes. Where would metastases be seen on MRI?", a: "Right occipital lobe - homonymous hemianopia (a full contralateral hemifield means the lesion is behind the chiasm, in the occipital lobe)." },
  { id: "na126", category: "Visual Pathway", q: "Explain the Marcus Gunn pupil mechanism.", a: "Caused by a CN II (optic nerve) lesion, classically optic neuritis in an MS flare. The affected eye under-senses light intensity (weak afferent signal), so the efferent CN III parasympathetic constriction output is attenuated for BOTH pupils. Shining light in the affected eye makes both pupils constrict less than when light is shone in the unaffected eye, giving the mere impression that the pupils dilate.", img: "/qimg/neuro/fig-050-079.webp", alt: "Illustration of the swinging flashlight test showing a relative afferent pupillary defect of the right eye" },
  // ===== NEUROANATOMY: Cavernous Sinus + Surgical Anatomy =====
  { id: "na127", category: "Cavernous Sinus", q: "45M after cranial surgery: the left pupil is larger than the right. Which letter on the cavernous sinus illustration is the pathology?", a: "D - CN III (oculomotor nerve); a lesion causes a down-and-out pupil and/or mydriasis. This illustration is exceedingly HY for Step 1. A = cavernous sinus, B = sphenoid sinus, C = internal carotid artery, E = trochlear nerve (CN IV), F = V1, G = abducens nerve (CN VI), H = V2.", img: "/qimg/neuro/fig-051-081.webp", alt: "Coronal illustration of the cavernous sinus with letters marking the sinus, sphenoid sinus, internal carotid artery, and cranial nerves III, IV, V1, V2, and VI" },
  { id: "na128", category: "Cavernous Sinus", q: "34M had a sinus infection treated with amoxicillin-clavulanate a week ago; now diplopia, ophthalmoplegia, headache, and a fever of 103. Diagnosis, mechanism, treatment?", a: "Cavernous sinus thrombosis - sinus infections ascend to the cavernous sinus via the valveless facial veins (through the superior and inferior ophthalmic veins). Sinus infection followed by fever, diplopia, and ophthalmoplegia is classic. Give IV antibiotics.", img: "/qimg/neuro/fig-051-081.webp", alt: "Coronal illustration of the cavernous sinus with letters marking the sinus, sphenoid sinus, internal carotid artery, and cranial nerves III, IV, V1, V2, and VI" },
  { id: "na129", category: "Cavernous Sinus", q: "41F has sphenoid sinus surgery and now neurologic dysfunction. What additional exam finding is likely, and why?", a: "Inability to abduct the eye - abducens (CN VI) injury. CN VI is the most medial nerve in the cavernous sinus, closest to the sphenoid sinus, so it is the most susceptible. Same answer if a prolactinoma with bitemporal hemianopsia expands laterally within the sella.", img: "/qimg/neuro/fig-051-081.webp", alt: "Coronal illustration of the cavernous sinus with letters marking the sinus, sphenoid sinus, internal carotid artery, and cranial nerves III, IV, V1, V2, and VI" },
  { id: "na130", category: "Surgical Anatomy", q: "22M needs a laminectomy. Which letter on the vertebra illustration is the correct surgical entrance to the neural canal?", a: "E - the lamina (hence laminectomy). A = transverse process, B = pedicle, C = vertebral body, D = facet joints, F = spinous process. Tangential factoid: the vertebral arteries (first branch of the subclavians) ascend through the transverse foramina of the cervical vertebrae.", img: "/qimg/neuro/fig-052-083.webp", alt: "Illustration of a vertebra with letters marking the transverse process, pedicle, vertebral body, facet joints, lamina, and spinous process" },
  { id: "na131", category: "Surgical Anatomy", q: "17M undergoing spinal surgery - a needle inserted posteriorly between the L3 and L4 vertebral arches must traverse which ligament to reach the spinal canal?", a: "The ligamentum flavum." },
  // ===== NEUROANATOMY: Dermatomes + Mixed Vignettes =====
  { id: "na132", category: "Surgical Anatomy", q: "24M with a lumbar disc herniation - which spinal ligament is pushed into the spinal root nerves?", a: "The posterior longitudinal ligament." },
  { id: "na133", category: "Dermatomes", q: "63M with pain radiating down the distal anterior thigh, knee, medial leg, and medial foot. Compression of the nerve root at which intervertebral foramina?", a: "L3-L4 (the L4 dermatome runs anterior thigh -> medial leg -> medial foot)." },
  { id: "na134", category: "Dermatomes", q: "HY dermatomes and reflexes: biceps jerk, triceps reflex, nipples, umbilicus, groin, knee jerk, ankle jerk and sole.", a: "C5 = biceps jerk, C7 = triceps reflex, T4 = nipples, T10 = umbilicus, L1 = groin, L3/4 = knee jerk, S1 = ankle jerk + sole of foot." },
  { id: "na135", category: "Dermatomes", q: "32F with gestational pemphigoid has itchy vesicles around the umbilicus. Which dermatome senses this?", a: "T10." },
  { id: "na136", category: "Mixed Vignettes", q: "52M: sudden PAINLESS vision loss in the right eye with a central scotoma; fundoscopy shows a pale opaque fundus and bright red fovea. Eight months later, what happens in the LEFT pupil when the right eye is illuminated?", a: "No constriction - the retinal ganglion cells of the right eye are destroyed (central retinal artery occlusion with a cherry-red spot). The afferent limb (CN II right) is dead, so neither direct nor consensual constriction occurs from light in that eye. Etiology: a carotid plaque launching off in HTN, or a mural thromboembolus from AF; vision loss is permanent." },
  { id: "na137", category: "Mixed Vignettes", q: "42F has diplopia but reads books normally, with decreased adduction of the left eye gazing right. Location of the demyelinating plaque?", a: "Left MLF - internuclear ophthalmoplegia. Reading normally means convergence is preserved, pointing away from CN III." },
  { id: "na138", category: "Mixed Vignettes", q: "81M has a stroke. Which CNS cell type clears necrotic tissue, and what else is that cell known for?", a: "Microglial cells - the macrophages of the CNS. They are also one of the major cellular reservoirs of HIV in the CNS." },
  { id: "na139", category: "Mixed Vignettes", q: "23F with migraines - which chemical mediator may contribute to her symptoms?", a: "Substance P." },
  { id: "na140", category: "Mixed Vignettes", q: "44M with long-standing alcoholism stumbles to the RIGHT when walking; Romberg sign is intact (negative). Location of the pathology, and the Romberg rule?", a: "Right side of the cerebellum - cerebellar lesions are always ipsilateral. Lateral parts cause ipsilateral limb ataxia; midline (vermis) lesions cause truncal ataxia. Romberg is POSITIVE when the ataxia comes from the dorsal columns (tabes dorsalis); a negative Romberg means cerebellar etiology on the USMLE." },
  { id: "na141", category: "Mixed Vignettes", q: "5F with recent vomiting, bilateral papilledema, impaired upward gaze, a shuffling gait, and a 2cm mass with enlarged lateral and third ventricles. Location of the mass and diagnosis?", a: "Pineal gland - Parinaud syndrome (upward gaze palsy from a pinealoma). Bottom line: brain tumor in a kid + cannot look up = pinealoma. Morning vomiting signals increased intracranial pressure." },
  { id: "na142", category: "Mixed Vignettes", q: "7M ingested a substance under the kitchen sink and is vomiting. Which part of the brain is responsible for the vomiting?", a: "The area postrema - the chemotactic trigger zone for emesis, located on the dorsal aspect of the medulla at the caudal fourth ventricle." },
  { id: "na143", category: "Mixed Vignettes", q: "51M with hereditary hemochromatosis has an isolated decrease in serum gonadotropins. Location of the pathology, and why not the pituitary?", a: "Hypothalamus - iron deposition there reduces GnRH. If the deposition were in the anterior pituitary, the other anterior pituitary hormones would fall too, not just LH and FSH." },
  { id: "na144", category: "Mixed Vignettes", q: "Which hormones does the anterior pituitary secrete, and which does the posterior pituitary store?", a: "Anterior: LH, FSH, TSH, ACTH, GH, prolactin. Posterior: vasopressin (ADH) and oxytocin - note these are only STORED there, synthesized in the hypothalamus." },
  { id: "na145", category: "Mixed Vignettes", q: "Hypothalamic releasing hormones: which anterior pituitary hormone does each of GnRH, TRH, CRH, GHRH, and dopamine control?", a: "GnRH stimulates LH and FSH; TRH stimulates TSH; CRH stimulates ACTH; GHRH stimulates GH; dopamine INHIBITS prolactin - the only inhibitory one." },
  { id: "na146", category: "Mixed Vignettes", q: "16F in an MVA has her pituitary stalk severed. Which hormone will INCREASE?", a: "Prolactin - all hypothalamic hormones are stimulatory except dopamine's inhibition of prolactin, so losing the stalk releases prolactin from inhibition." },
  { id: "na147", category: "Mixed Vignettes", q: "65M, BP 140/100, 2/5 strength in the left leg with brisk reflexes. Which vessel?", a: "Right anterior cerebral artery - leg weakness is ACA territory (contralateral, UMN signs)." },
  { id: "na148", category: "Mixed Vignettes", q: "61F brought in by police, confused and disheveled with a broad-based gait and nystagmus; tox screens negative. What will be atrophic on MRI?", a: "The mammillary bodies - Wernicke encephalopathy. Remember ACOW: Ataxia, Confusion, Ophthalmoplegia, Wernicke." },
  { id: "na149", category: "Mixed Vignettes", q: "55M has two weeks of constant, intense left-arm pain, five months after a stroke that cost him sensation on his left side. Where is the damage that causes this pain?", a: "Right thalamus - thalamic pain syndrome (Dejerine-Roussy), a HY post-stroke cause of pain." },
  { id: "na150", category: "Mixed Vignettes", q: "42F hit in the left eye by a golf ball: diplopia, periorbital swelling, enophthalmos, impaired upward gaze, decreased sensation over the left zygoma, orbital floor fracture on x-ray. Which two muscles are entrapped?", a: "The inferior rectus and inferior oblique - hence the impaired upward gaze." },
  { id: "na151", category: "Mixed Vignettes", q: "77M with sudden left-eye miosis, left ptosis, dysphagia, difficulty speaking, and pain/temperature loss on the left face and right body. Which artery?", a: "Left posterior inferior cerebellar artery (PICA) - lateral medullary syndrome. Horner syndrome plus crossed sensory loss is the HY giveaway." },
  { id: "na152", category: "Mixed Vignettes", q: "15M gets pain and tingling in her right hand when backpacking; it resolves five minutes after taking the pack off. Diagnosis?", a: "Thoracic outlet syndrome - compression by the backpack straps, resolving when the load is removed." },
  { id: "na153", category: "Mixed Vignettes", q: "65M with T2DM, HTN, and hyperlipidemia: new quadriplegia, impaired horizontal eye movements with vertical movements intact, dysarthric speech. Which part of the brain is affected?", a: "The pons - locked-in syndrome from a basilar artery stroke: quadriplegia + aphonia + impaired horizontal eye movements." },
  { id: "na154", category: "Mixed Vignettes", q: "3M with moderate strabismus will develop depth-perception deficits if untreated. Calcium entry through which receptor mediates this competitive process in the visual cortex?", a: "NMDA (glutamate) receptors. Weird but handle it. This is also why strabismus is surgically corrected in early childhood - otherwise normal binocular vision never develops." },
  { id: "na155", category: "Mixed Vignettes", q: "23M with an inferonasal 'bleeding' of the pupil - incomplete closure of the embryonic fissure of which structure, and what syndrome?", a: "The iris. CHARGE syndrome presents with coloboma of the eye, where the iris fails to develop properly and the pupil looks like it bleeds inferonasally.", img: "/qimg/neuro/fig-058-087.webp", alt: "Photograph of an eye showing an inferonasal iris coloboma" },
  { id: "na156", category: "Mixed Vignettes", q: "57F with invasive gallbladder cancer has three weeks of severe left-sided back and abdominal pain. An operation to relieve the pain would target which spinal tract?", a: "The RIGHT spinothalamic tract - it carries pain contralaterally (percutaneous cordotomy)." },
  { id: "na157", category: "Mixed Vignettes", q: "An MS patient has urge incontinence, optic neuritis, and a POSITIVE Romberg sign. Which tract carries the vibration/proprioception loss of the lower limbs seen here, versus the upper-limb equivalent?", a: "Fasciculus gracilis for the lower limbs; fasciculus cuneatus for the upper limbs. The positive Romberg points to the dorsal columns." },
  { id: "na158", category: "Mixed Vignettes", q: "68M has a TIA with new-onset anterograde amnesia. What is the most likely affected location?", a: "The hippocampus - very sensitive to ischemic insult. It is also sometimes the answer for Alzheimer disease (progressive shrinking of the hippocampus and nucleus basalis of Meynert)." },
  { id: "na159", category: "Mixed Vignettes", q: "34F with left eye pain, blurry vision, progressive weakness of the right arm and both legs, optic disc swelling, and multiple T2 bright white-matter lesions on MRI. Which cell is attacked, and what makes the myelin?", a: "Oligodendrocytes - T cell-mediated destruction in MS. Oligodendrocytes make myelin in the CNS; Schwann cells make myelin in the PNS (including the cranial nerves, which are PNS). Schwann cell destruction in the PNS is Guillain-Barre." },
  { id: "na160", category: "Mixed Vignettes", q: "42F: four months of abnormal tingling that started in the right hand and progressed to the right arm and right side of the face. In which gyrus is the lesion?", a: "The left post-central gyrus - posterior to the central sulcus, where the primary sensory cortex is. Sensory symptoms marching up one side map to the contralateral sensory strip." },
  { id: "na161", category: "Mixed Vignettes", q: "44M with progressive ataxia, unsteady gait, and left-sided intention tremors. Which brain area is damaged?", a: "Left cerebellar hemisphere - cerebellar lesions cause IPSILATERAL signs." },
  { id: "na162", category: "Mixed Vignettes", q: "72F: loss of pain and temperature on the left face and right body, paralyzed left vocal cords, and loss of the gag reflex on the left. Which part of the brainstem?", a: "Left dorsolateral medulla - lateral medullary syndrome with CN IX/X dysfunction. The vocal cords run on the recurrent laryngeal nerve (of vagus); the gag reflex is CN IX afferent, CN X efferent." },
  { id: "na163", category: "Mixed Vignettes", q: "54F with four days of hoarseness and difficulty swallowing cannot elevate the left side of her palate. Which cranial nerve?", a: "Left vagus nerve (CN X) - failure to elevate the ipsilateral palate causes contralateral uvula deviation." },
  { id: "na164", category: "Mixed Vignettes", q: "54M with HTN can no longer recognize faces, and cannot recognize objects unless he touches them or hears them. Which artery supplies the damaged area?", a: "Posterior cerebral artery - prosopagnosia (faces) and visual agnosia (objects) localize to the inferior occipitotemporal cortex, PCA territory." },
  { id: "na165", category: "Mixed Vignettes", q: "45M with uvula deviation to the right and dysphagia - which tongue muscle might be affected?", a: "Palatoglossus - the one tongue muscle innervated by CN X; all the others are CN XII." },
  { id: "na166", category: "Mixed Vignettes", q: "29M after an MVA: hematoma over both mastoid processes, rhinorrhea, otorrhea, raccoon eyes. Diagnosis?", a: "Base of skull fracture - that tetrad is classic (Battle sign, CSF leaks, raccoon eyes)." },
  { id: "na167", category: "Mixed Vignettes", q: "31F post-MVA: GCS 6, BP 165/90, RR 10, HR 55. What is the mechanism of her hypertension?", a: "Increased intracranial pressure - the Cushing triad is hypertension, bradycardia, and bradypnea." },
  { id: "na168", category: "Mixed Vignettes", q: "59F with metastatic breast cancer has an absent corneal reflex on the right. Metastases to which cranial nerve exit point could cause this?", a: "The superior orbital fissure - the exit point of the ophthalmic branch of the trigeminal nerve (V1), the afferent limb of the corneal reflex. Standing Room Only: Superior orbital fissure, foramen Rotundum, foramen Ovale for V1, V2, V3." },
  { id: "na169", category: "Mixed Vignettes", q: "24M treated with IV acyclovir for herpes encephalitis now has hyperphagia, hypersexuality, and hyperorality. Diagnosis?", a: "Kluver-Bucy syndrome - bilateral amygdala lesions, a rare complication of HSV encephalitis." },
  { id: "na170", category: "Mixed Vignettes", q: "23M nearly drowned with brain hypoxia. What change might be seen in his hippocampi, and what deficit results?", a: "Red neurons - the pathologic staining pattern of neurons during acute hypoxic injury. The hippocampi are notably susceptible to ischemia, and the result is anterograde amnesia." },
  { id: "na171", category: "Mixed Vignettes", q: "40F feels the room is spinning, sometimes with vomiting, and the physician reproduces it with the Dix-Hallpike maneuver. Mechanism and treatment?", a: "A posterior semicircular canal otolith - benign paroxysmal positional vertigo (BPPV). Treat with the Epley maneuver." },
  { id: "na172", category: "Mixed Vignettes", q: "40F after a viral infection: tinnitus + hearing loss + vertigo. And if it were vertigo alone?", a: "Tinnitus + hearing loss + vertigo = labyrinthitis. Vertigo alone after a viral infection = vestibular neuritis." },
  { id: "na173", category: "Mixed Vignettes", q: "31M: warm water instilled into the left ear causes nystagmus, but warm water in the right ear does not. Where is the lesion?", a: "The right-sided vestibular apparatus - if nystagmus fails to occur on the warm (stimulated) side, that side is weak. Warm water moves endolymph as if the head turned ipsilaterally: eyes drift contralateral, nystagmus beats ipsilateral; cold water does the opposite. This is the vestibular caloric reflex test." },
  { id: "na174", category: "Mixed Vignettes", q: "Shining light in either eye causing direct and consensual pupillary constriction tests the functional integrity of what?", a: "The midbrain - specifically the Edinger-Westphal nucleus." },
  { id: "na175", category: "Mixed Vignettes", q: "24M: the left eye fails to constrict when light is shone in EITHER eye. Where is the lesion?", a: "The left oculomotor nerve (CN III) - the efferent limb for that eye is dead, so it cannot constrict no matter which eye senses the light." },
  { id: "na176", category: "Mixed Vignettes", q: "69M, smoker for 50 years: constricted left pupil, droopy left eyelid, dry skin on the left side of the face. Where is the lesion?", a: "A Pancoast tumor of the lung impinging on the superior cervical ganglion - Horner syndrome (miosis, ptosis, anhidrosis)." },
  { id: "na177", category: "Mixed Vignettes", q: "24M with burning vesicular lesions around the lips. What is the mechanism of this pathogen's presentation?", a: "Reactivation in sensory neurons - herpes labialis (HSV1/2). The virus lies dormant in the trigeminal nerve (V2 maxillary, V3 mandibular branches)." },
  { id: "na178", category: "Mixed Vignettes", q: "3-day-old male born at home, umbilical cord tied with twine, now arching his back. Mechanism of the disease process?", a: "Blockade of inhibitory neurotransmitter release - tetanus toxin decreases presynaptic release of GABA and glycine by inhibiting SNARE protein. If the USMLE shows a drawing of where the toxin acts, the answer is inside the presynaptic terminal." },
  { id: "na179", category: "Hearing Tests", q: "Rinne test: how is it done, and how do normal, conductive, and sensorineural ears read out?", a: "A vibrating tuning fork goes on the mastoid (bone conduction); when the patient stops hearing it, it moves in front of the ear canal (air conduction). Normal and sensorineural loss: AC > BC. Conductive loss: BC > AC." },
  { id: "na180", category: "Hearing Tests", q: "Weber test: how is it done, and which way does it lateralize in conductive versus sensorineural loss?", a: "The fork goes on the center of the forehead; louder in one ear is lateralization. Conductive loss lateralizes to the AFFECTED ear; sensorineural loss lateralizes to the UNAFFECTED ear. Rinne stays AC > BC in sensorineural loss, flips to BC > AC in conductive." },
];
export default neuroAnatomyQuestions;
